# Verification: show newly created alarms by their IDs
expected_ids = [743, 744, 745, 746]
expected = {
    743: {'label':'Quality Assurance and Testing Roundtable','time':'12:55','repeat_days':['monday'],'snooze_minutes':5},
    744: {'label':'Company All-Hands Town Hall','time':'12:55','repeat_days':['wednesday'],'snooze_minutes':5},
    745: {'label':'Marketing Strategy Brainstorm Session','time':'13:25','repeat_days':['friday'],'snooze_minutes':5},
    746: {'label':'Leadership Training Session','time':'14:25','repeat_days':['friday'],'snooze_minutes':5},
}

results = {}
for aid in expected_ids:
    resp = apis.phone.show_alarm(access_token=phone_token, alarm_id=aid)
    results[aid] = resp
    print('alarm_id', aid)
    for k in ['time','repeat_days','label','snooze_minutes','enabled']:
        print(' ', k, resp.get(k))

# Check criteria
ok=True
for aid, ex in expected.items():
    r = results.get(aid, {})
    if r.get('label') != ex['label']:
        ok=False
        print('MISMATCH label', aid, r.get('label'), '!=', ex['label'])
    if r.get('time') != ex['time']:
        ok=False
        print('MISMATCH time', aid, r.get('time'), '!=', ex['time'])
    if [d.lower() for d in (r.get('repeat_days') or [])] != [d.lower() for d in ex['repeat_days']]:
        ok=False
        print('MISMATCH repeat_days', aid, r.get('repeat_days'), '!=', ex['repeat_days'])
    # snooze_minutes in API seems float
    if float(r.get('snooze_minutes')) != float(ex['snooze_minutes']):
        ok=False
        print('MISMATCH snooze_minutes', aid, r.get('snooze_minutes'), '!=', ex['snooze_minutes'])

print('verification_ok', ok)
